  s += textureLod(uPlayerShadow, vec3(c.xy + vec2(0.5, -1.5) * ts, z), 0.0);
  s += textureLod(uPlayerShadow, vec3(c.xy + vec2(1.5, 0.5) * ts, z), 0.0);
