  v1 = vec4(P.mega.u, P.mega.gu, P.bmix);
  v2 = vec4(P.mega.a, P.tint);
  v3 = vec4(P.prim.u, P.prim.gu, P.giant.u);
  v4 = vec4(P.prim.a, P.giant.gu.x);
  v5 = vec4(P.sec.u, P.sec.gu, P.giant.gu.y);
  v6 = vec4(P.sec.a, P.giant.a.x);
  v7 = vec4(P.small.u, P.small.gu, P.giant.a.y);
  v8 = vec4(P.small.a, P.giant.a.z);
