    if (S.lf > 0.0 && int(S.lfLook + 0.5) == LF_VOLCANO) nm |= NB_SHADE_CRACK;
    if (desertOn > 0.0) nm |= NB_SHADE_SAND;
    if (cold.x > 0.0) nm |= NB_SHADE_SNOW;
